import fs from 'node:fs/promises';
const source=await fs.readFile(new URL('../automation-lab/student-kit/Setup.ps1',import.meta.url),'utf8');
const body=source.replace(/^param\([^\n]+\)\r?\n/,'$CheckOnly=$env:MQA_CHECK_ONLY -eq "1"\n$UpdateTools=$env:MQA_UPDATE_TOOLS -eq "1"\n').replaceAll('$PSScriptRoot','$env:MQA_KIT_ROOT').replace(/\r\n/g,'\n');
const header=`#!/usr/bin/env bash
# Generated by scripts/build-git-bash-setup.mjs from Setup.ps1.
# Windows Git Bash only. Run from an extracted Academy Windows kit:
# bash Setup.sh
# Uses inline PowerShell; never opens a .ps1 or changes execution policy.
set -euo pipefail
case "$(uname -s)" in MINGW*|MSYS*) ;; *) echo 'Use Git Bash on Windows. This is not a WSL/Linux installer.' >&2; exit 1;; esac
for tool in powershell.exe cygpath; do
  command -v "$tool" >/dev/null || { echo "Missing $tool. Open Git Bash on Windows." >&2; exit 1; }
done
export MQA_CHECK_ONLY=0 MQA_UPDATE_TOOLS=0
for option in "$@"; do
  case "$option" in
    --check-only|-CheckOnly) export MQA_CHECK_ONLY=1 ;;
    --update-tools|-UpdateTools) export MQA_UPDATE_TOOLS=1 ;;
    *) echo 'Usage: bash Setup.sh [--check-only] [--update-tools]' >&2; exit 1 ;;
  esac
done
kit_dir="$(cd -- "$(dirname -- "$0")" && pwd -P)"
if [[ ! -f "$kit_dir/kit-manifest.json" || ! -f "$kit_dir/lab.mjs" ]]; then
  echo 'Save Setup.sh beside Setup.cmd, kit-manifest.json and lab.mjs in the extracted Windows kit.' >&2
  exit 1
fi
export MQA_KIT_ROOT="$(cygpath -w "$kit_dir")"
export MSYS_NO_PATHCONV=1
setup_code=$(cat <<'ACADEMY_POWERSHELL'
`;
const target=new URL('../automation-lab/student-kit/Setup.sh',import.meta.url);
const generated=header+body+"\nACADEMY_POWERSHELL\n)\npowershell.exe -NoProfile -Command \"$setup_code\"\n";
if(process.argv.includes('--check')){
  if((await fs.readFile(target,'utf8')).replace(/\r\n/g,'\n')!==generated)throw Error('Setup.sh is stale. Run the generator.');
  console.log('Setup.sh matches the shared Windows installer.');
}else{
  await fs.writeFile(target,generated);
  console.log('Generated Git Bash setup from shared Windows installer.');
}
